import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import { IssueBlockedError, assertIssueCanComplete } from "./issue-dependency-service";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
